 'use strict';
(()=>{
 const content=document.getElementById('content'),dialog=document.createElement('dialog');dialog.className='info-dialog';dialog.innerHTML='<div class="dialog-heading"><h2 id="workspace-dialog-title"></h2><button type="button" aria-label="닫기">닫기 ✕</button></div><div class="dialog-body"></div>';dialog.setAttribute('aria-labelledby','workspace-dialog-title');document.body.append(dialog);
 let source=null,nodes=[],returnFocus=null,pending=null,reopenText=null,reopenId=null;
 function refresh(){layout();if(reopenText||reopenId){const text=reopenText,id=reopenId;reopenText=null;reopenId=null;const details=id?document.getElementById(id):null,summary=details?.querySelector('summary')||[...content.querySelectorAll('summary')].find(x=>x.textContent===text);if(summary)open(summary.parentElement,summary);}restore();}
 function suspend(fn){fn();}
 function close(){if(!source)return;suspend(()=>{for(const n of nodes)source.append(n);source.querySelector('summary')?.setAttribute('aria-expanded','false');if(source.classList.contains('status-summary')){const side=source.querySelector('.workspace-side');if(side)content.querySelector('.workspace-shell')?.append(side);}source=null;nodes=[];dialog.close();});if(returnFocus?.isConnected){const focus=returnFocus.getClientRects().length?returnFocus:content.querySelector('.status-summary>summary');focus?.focus({preventScroll:true});}}
 function open(details,summary){suspend(()=>{if(details.classList.contains('status-summary')){const side=content.querySelector('.workspace-shell>.workspace-side');if(side){details.querySelector('.status-content').append(side);side.hidden=false;}}source=details;returnFocus=summary;summary.setAttribute('aria-expanded','true');nodes=[...details.childNodes].filter(n=>n!==summary);dialog.querySelector('h2').textContent=summary.textContent;dialog.querySelector('.dialog-body').replaceChildren(...nodes);dialog.showModal();dialog.querySelector('button').focus();});}
 document.addEventListener('click',e=>{const summary=e.target.closest('summary');if(summary&&summary.parentElement.tagName==='DETAILS'&&!document.body.classList.contains('battle-mode')&&!dialog.contains(summary)&&!summary.parentElement.hasAttribute('data-inline')){e.preventDefault();open(summary.parentElement,summary);}});
 dialog.querySelector('button').addEventListener('click',close);dialog.addEventListener('cancel',e=>{e.preventDefault();close();});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();}});
 const find=sel=>content.querySelector(sel)||dialog.querySelector(sel);
 function scrollState(selectors){const scroll={};for(const sel of selectors){const n=find(sel);if(n)scroll[sel]={x:n.scrollLeft,y:n.scrollTop};}return scroll;}
 function restore(){if(!pending)return;const p=pending;pending=null;if(content.dataset.workspace!==p.screen)return;for(const saved of p.disclosures||[]){const d=saved.id?find('#'+saved.id):[...dialog.querySelectorAll('details')].find(d=>d.querySelector('summary')?.textContent===saved.text);if(d)d.open=true;}for(const [sel,v] of Object.entries(p.scroll)){const e=find(sel);if(e){e.scrollLeft=v.x;e.scrollTop=v.y;}}const actions=[...content.querySelectorAll('[data-action]'),...dialog.querySelectorAll('[data-action]')],match=p.selector?find(p.selector):p.edit?find('[data-edit="'+p.edit+'"]'):actions.find(e=>e.dataset.action===p.action&&(!p.id||e.dataset.id===p.id)&&(!p.key||e.dataset.key===p.key)&&(!p.token||e.dataset.token===p.token)&&(p.role===undefined||e.dataset.role===p.role))||actions.find(e=>p.id&&e.dataset.id===p.id);if(match){const focus=match.disabled?match.parentElement.querySelector('button:not(:disabled)'):match;focus?.focus({preventScroll:true});}}
 document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;if(['editor-select','editor-reset','plus','minus','copy','discard-card','restore-card','reward-preview','swap-cancel','practice-copy','practice-preset','practice-reset','practice-previous','starting-preset','starting-custom','starting-challenge','stance-prep','formation-slot','formation-reset','formation-cancel','formation-original','formation-undo'].includes(b.dataset.action)){const scroll=scrollState(['.workspace-main','.workspace-body','.workspace-side','.workspace-rail','.deck-card-list','.reward-planner','.dialog-body','.practice-pool',...(['plus','minus','copy','editor-reset'].includes(b.dataset.action)?['.deck-selected .visual-card']:[])]);pending={screen:content.dataset.workspace,scroll,action:b.dataset.action,id:b.dataset.id,key:b.dataset.key,token:b.dataset.token,edit:b.dataset.edit,role:b.dataset.role,disclosures:[...dialog.querySelectorAll('details[open]')].map(d=>({id:d.id,text:d.querySelector('summary')?.textContent}))};}if(['discard-card','restore-card','practice-copy','stance-prep','formation-slot','formation-reset','formation-cancel','formation-original','formation-undo'].includes(b.dataset.action)&&source){reopenText=source.querySelector('summary').textContent;reopenId=source.id||null;}},true);
 document.addEventListener('change',e=>{if(['reward-out','deck-owner','deck-trait','practice-basics','prep-range'].includes(e.target.id)){pending={screen:content.dataset.workspace,scroll:scrollState(['.workspace-main','.workspace-body','.reward-planner']),selector:'#'+e.target.id};}},true);
 function compact(){document.body.classList.toggle('workspace-short',innerHeight<720||innerWidth<360);}
 window.addEventListener('resize',compact);compact();
 function layout(){if(content.querySelector('.workspace-main'))return;const battle=document.body.classList.contains('battle-mode');document.body.classList.toggle('workspace-mode',!battle);if(battle)return;
 suspend(()=>{
  const original=[...content.children],head=original.find(x=>x.classList.contains('section-head')),main=document.createElement('div'),side=document.createElement('aside'),shell=document.createElement('div');main.className='workspace-main';side.className='workspace-side';shell.className='workspace-shell';side.setAttribute('aria-label','파티와 원정 정보');
  const state=content.dataset.screen,isMap=state==='map',isReward=state==='reward',isEditor=state==='deck',isStarting=state==='starting',isLoot=state==='loot';
  content.dataset.workspace=isMap?'map':isReward?'reward':isEditor?'editor':isStarting?'starting':isLoot?'loot':'other';
  for(const n of original){if(n===head)continue;const secondary=n.matches('.party-summary,.trait-panel,.prep-panel,.chapter-list,.challenge-active,.upcoming-plan')||n.tagName==='DETAILS'&&!n.matches('.challenge-picker,.growth-review');(secondary?side:main).append(n);}
  if(isMap){const chapter=side.querySelector('.chapter-list');if(chapter){const d=document.createElement('details');d.className='panel route-overview';d.innerHTML='<summary>전체 경로</summary>';chapter.replaceWith(d);d.append(chapter);}}
  if(side.children.length){const holder=document.createElement('details');holder.className='panel status-summary';holder.innerHTML='<summary>'+(isMap?'파티·특성·전투 준비':isEditor?'덱 특성·대기 카드':isReward?'덱 특성·다음 교전':content.querySelector('.growth-story')?'전투 상세·파티 상태':'추가 정보·파티 상태')+'</summary>';const copyArea=document.createElement('div');copyArea.className='status-content';holder.append(copyArea);shell._statusHolder=holder;}
  if(head)content.replaceChildren(head,shell);else content.replaceChildren(shell);shell.append(main,side);if(!side.children.length)side.hidden=true;const holder=shell._statusHolder;if(holder){content.insertBefore(holder,shell);}
  if(isMap){const dock=document.createElement('div');dock.className='workspace-commit action-dock';for(const b of side.querySelectorAll('[data-action="run-deck"],[data-action="undo-deck"],[data-action="formation-open"]'))dock.append(b);for(const room of main.querySelectorAll('.room-preview')){const b=room.querySelector('[data-action="enter"]');if(b){b.textContent=room.querySelector('h3').textContent+' · 선택';dock.append(b);}}main.append(dock);}
  if(isStarting){const options=main.querySelector('.starting-options');if(options)options.classList.add('workspace-options');}
  if(isReward){const controls=main.querySelector('.action-dock,[data-action="skip"]')?.closest('.action-dock')||main.querySelector('[data-action="skip"]')?.parentElement;if(controls){controls.classList.add('workspace-commit');main.append(controls);}}
  if(isStarting){const controls=main.querySelector('[data-action="starting-confirm"]')?.parentElement;if(controls){controls.classList.add('workspace-commit');main.append(controls);}}
  if(isEditor){const controls=main.querySelector('[data-action="commit"]')?.parentElement;if(controls)controls.classList.add('workspace-commit');}
  if(!main.querySelector(':scope>.workspace-commit')){const controls=main.querySelector('.reward-exchange>.row:last-child')||main.querySelector('[data-action="camp-card"]')?.parentElement;const next=main.querySelector('[data-action="next"],[data-action="reward-open"],[data-action="complete"],[data-action="skip"]');if(controls){controls.classList.add('workspace-commit','action-dock');main.append(controls);}else if(next){const dock=document.createElement('div');dock.className='workspace-commit action-dock';dock.append(next);main.append(dock);}}
  const storyButton=main.querySelector('.growth-story [data-action="practice-open"]'),storyDock=main.querySelector(':scope>.workspace-commit');if(storyButton&&storyDock)storyDock.prepend(storyButton);
  const rail=main.querySelector('.card-area:has([data-action="pick-reward"]),.upgrade-options,.swap-card-grid,.editor-list,.workspace-options');
  if(rail){rail.classList.add('workspace-rail');const nav=document.createElement('div');nav.className='rail-nav';const label=document.createElement('span');label.textContent='좌우로 카드·선택지 보기';for(const [text,d] of [['← 이전',-1],['다음 →',1]]){const b=document.createElement('button');b.type='button';b.textContent=text;b.addEventListener('click',()=>rail.scrollBy({left:d*Math.max(150,rail.clientWidth*.8),behavior:'smooth'}));nav.append(b);}nav.append(label);rail.before(nav);}
  const dock=main.querySelector(':scope>.workspace-commit');if(dock){const body=document.createElement('div');body.className='workspace-body';for(const n of [...main.children])if(n!==dock)body.append(n);main.prepend(body);main.classList.add('has-action-dock');}
 });
 }
 window.WorkspaceUI={beforeRender:close,refresh,openDetails:details=>{if(details)open(details,details.querySelector('summary'));}};refresh();
})();

